def response(self) -> str:
    if self.success:
        assert self.answer is not None
        return self.answer

    assert self.error is not None
    return self.error

@classmethod
def completed(
    cls,
    *,
    answer: str,
    stop_reason: str = "completed",
) -> "AgentRunOutcome":
    return cls(
        success=True,
        answer=answer,
        stop_reason=stop_reason,
    )

@classmethod
def failed(
    cls,
    *,
    error: str,
    stop_reason: str,
) -> "AgentRunOutcome":
    return cls(
        success=False,
        error=error,
        stop_reason=stop_reason,
