def finish(self, result: str | None = None) -> None:
    """
    Close the plan after the Agent has produced its final answer.

    During the current transitional stage, unfinished steps are marked as skipped. Later, controlled plan-progress updates should normally complete or skip steps before this method is called.
    """

    if self.status == "completed":
        if result is not None:
            self.result = result
        return

    if self.status == "failed":
        raise PlanTransitionError("Cannot finish a failed plan.")

    for step in self.steps:
        if step.status in ("pending", "in_progress"):
            step.skip("Agent finished before this step was explicitly updated.")

    self.current_step_index = len(self.steps)
    self.status = "completed"
    self.result = result
    self.error = None

def fail(self, error: str) -> None:
    if self.status == "failed":
        return

    if self.status == "completed":
        raise PlanTransitionError("Cannot fail a completed plan.")

    error = error.strip()

    if not error:
        raise PlanValidationError("Plan failure error must not be empty.")

    step = self.current_step

    if step is not None and step.status in ("pending", "in_progress"):
        step.fail(error)

    self.status = "failed"
    self.error = error

def _require_in_progress(self) -> None:
    if self.status != "in_progress":
        raise PlanTransitionError(
            f"Plan must be in progress before its current step can be updated; current status is '{self.status}'."
        )

def _move_to_next_step(self) -> None:
    self.current_step_index += 1

    if self.current_step_index >= len(self.steps):
        self.status = "completed"
        return

    next_step = self.current_step

    if next_step is None:
        raise PlanTransitionError("Failed to locate the next plan step.")

    next_step.start()

def __init__(
    self,
    *,
    chat_function: PlanEvaluationChatFunction | None = None,
) -> None:
    self._chat = chat_function or chat

def evaluate_progress(
    self,
    *,
    plan: AgentPlan,
    state: AgentState[Any],
    latest_evidence: list[dict[str, Any]],
    updates_remaining: int,
    max_total_steps: int,
    max_added_steps_per_update: int,
) -> PlanUpdate:
    if plan.status != "in_progress":
        raise PlanEvaluationError(
            "Plan progress can only be evaluated while " "the plan is in progress."
        )

    if plan.current_step is None:
        raise PlanEvaluationError("The running plan has no current step.")

    if updates_remaining < 0:
        raise ValueError("updates_remaining must not be negative.")

    if max_total_steps <= 0:
        raise ValueError("max_total_steps must be greater than zero.")

    if max_added_steps_per_update <= 0:
        raise ValueError("max_added_steps_per_update must be greater " "than zero.")

    state_payload = state.to_dict()

    # The plan is supplied separately below. Removing it avoids
    # sending the same data to the evaluator twice.
    state_payload.pop("plan", None)

    evaluation_payload = {
        "plan": plan.to_dict(),
        "agent_state": state_payload,
        "latest_evidence": latest_evidence,
        "plan_update_limits": {
            "updates_remaining": updates_remaining,
            "max_total_steps": max_total_steps,
            "max_added_steps_per_update": (max_added_steps_per_update),
        },
    }

    messages = [
        {
            "role": "system",
            "content": PLAN_EVALUATOR_SYSTEM_PROMPT,
        },
        {
            "role": "user",
            "content": (
                "Evaluate the plan progress using the "
                "following execution data:\n\n"
                + json.dumps(
                    evaluation_payload,
                    ensure_ascii=False,
                    default=str,
                )
            ),
        },
    ]

    try:
        response = self._chat(messages, [])
    except LLMClientError as error:
        raise PlanEvaluationError(
            "Plan evaluation request failed: " f"{error}"
        ) from error

    content = getattr(response, "content", None)

