def _parse_json_object(
    self,
    content: str,
) -> dict[str, Any]:
    text = content.strip()

    # A small defensive fallback for models that still return a fenced
    # JSON block despite the prompt.
    if text.startswith("```"):
        lines = text.splitlines()

        if lines:
            lines = lines[1:]

        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]

            text = "\n".join(lines).strip()

    try:
        payload = json.loads(text)
    except json.JSONDecodeError as error:
        raise PlannerResponseError(
            f"Planner returned invalid JSON: {error}"
        ) from error

    if not isinstance(payload, dict):
        raise PlannerResponseError("Planner response must be a JSON object.")

    unknown_fields = set(payload) - {"steps"}

    if unknown_fields:
        raise PlannerResponseError(
            "Planner response contains unsupported fields: "
            + ", ".join(sorted(unknown_fields))
        )

    return payload

