def _parse_step_specs(
    self,
    payload: dict[str, Any],
) -> list[PlanStepSpec]:
    raw_steps = payload.get("steps")

    if not isinstance(raw_steps, list):
        raise PlannerResponseError("Planner response field 'steps' must be a list.")

    if not raw_steps:
        raise PlannerResponseError("Planner must return at least one step.")

    if len(raw_steps) > self.max_plan_steps:
        raise PlannerResponseError(
            f"Planner returned {len(raw_steps)} steps, but the limit is {self.max_plan_steps}."
        )

    step_specs: list[PlanStepSpec] = []

    for index, raw_step in enumerate(raw_steps, start=1):
        if not isinstance(raw_step, dict):
            raise PlannerResponseError(
                f"Planner step {index} must be a JSON object."
            )

        allowed_fields = {
            "description",
            "completion_criteria",
        }

        unknown_fields = set(raw_step) - allowed_fields

        if unknown_fields:
            raise PlannerResponseError(
                f"Planner step {index} contains unsupported fields: {', '.join(sorted(unknown_fields))}"
            )

        description = raw_step.get("description")
        completion_criteria = raw_step.get("completion_criteria")

        if not isinstance(description, str):
            raise PlannerResponseError(
                f"Planner step {index} field 'description' must be a string."
            )

        if completion_criteria is not None and not isinstance(
            completion_criteria, str
        ):
            raise PlannerResponseError(
                f"Planner step {index} field 'completion_criteria' must be a string or null."
            )

        try:
            step_specs.append(
                PlanStepSpec(
                    description=description,
                    completion_criteria=completion_criteria,
                )
            )
        except PlanValidationError as error:
            raise PlannerResponseError(
                f"Planner step {index} is invalid: {error}"
            ) from error

    return step_specs

