def print_failures(
    summary: RetrievalEvaluationSummary,
    max_results: int = 5,
) -> None:
    print()
    print(f"--- {summary.retriever_name} " "misses ---")

    for result in summary.case_results:
        if result.hit_at(5):
            continue

        print()
        print(f"[{result.case_id}]")
        print(result.query)

        for search_result in result.retrieved[:max_results]:
            chunk = search_result.chunk

            print(
                f"  #{search_result.rank} "
                f"{chunk.source} :: "
                f"{chunk.metadata.get('symbol')}"
            )

def print_case_details(
    summary: RetrievalEvaluationSummary,
    cases: list[RetrievalEvaluationCase],
    max_results: int = 5,
) -> None:
    case_by_id = {case.id: case for case in cases}

    print()
    print(f"--- {summary.retriever_name} " "incomplete cases ---")

    for result in summary.case_results:
        if result.complete_at(8):
            continue

        case = case_by_id[result.case_id]

        print()
        print(f"[{result.case_id}]")
        print(result.query)

        print("Expected groups:")

        for index, group in enumerate(case.relevant_groups):
            rank = result.group_first_ranks[index]

            print(f"  [{group.name}] " f"rank={rank}")

            for target in group.alternatives:
                print("    - " f"{target.source} :: " f"{target.symbol}")

        print("Retrieved:")

        for search_result in result.retrieved[:max_results]:
            chunk = search_result.chunk

            print(
                f"  #{search_result.rank} "
                f"{chunk.source} :: "
                f"{chunk.metadata.get('symbol')}"
            )

def print_query_expansions(
    query_expander,
    cases,
) -> None:
    print()
    print("=== Query Expansions ===")

    for case in cases:
        rewrites = query_expander.expand(case.query)

        print()
        print(f"[{case.id}]")

        print(f"Original: {case.query}")

        for index, rewrite in enumerate(
            rewrites,
            start=1,
        ):
            print(f"Rewrite {index}: " f"{rewrite}")

def __init__(
    self,
    expansions: dict[
        str,
        tuple[str, ...],
    ],
) -> None:
    self.expansions = expansions

@classmethod
def from_json(
    cls,
    path: str | Path,
) -> "FrozenQueryExpander":
    source_path = Path(path)

    with source_path.open(
        "r",
        encoding="utf-8",
    ) as file:
        payload = json.load(file)

    if not isinstance(payload, list):
        raise ValueError("Query expansion dataset " "must contain a JSON list")

    expansions: dict[
        str,
        tuple[str, ...],
    ] = {}

    for item in payload:
        if not isinstance(item, dict):
            raise ValueError("Each query expansion " "must be an object")

        query = item.get("query")
        rewrites = item.get("rewrites")

        if not isinstance(query, str) or not query.strip():
            raise ValueError("Query must be a " "non-empty string")

        if not isinstance(
            rewrites,
            list,
        ):
            raise ValueError("rewrites must be a list")

        normalized_rewrites: list[str] = []

        for rewrite in rewrites:
            if not isinstance(
                rewrite,
                str,
            ):
                raise ValueError("Each rewrite must " "be a string")

            rewrite = rewrite.strip()

            if rewrite:
                normalized_rewrites.append(rewrite)

        expansions[query.strip()] = tuple(normalized_rewrites)

    return cls(expansions)

