def matches(
    self,
    chunk: Chunk,
) -> bool:
    if chunk.source != self.source:
        return False

    metadata = chunk.metadata

    if self.symbol is not None and metadata.get("symbol") != self.symbol:
        return False

    if (
        self.symbol_type is not None
        and metadata.get("symbol_type") != self.symbol_type
    ):
        return False

    return True

