def _build_searchable_text(
    chunk: Chunk,
) -> str:
    """
    为 BM25 构造代码检索文本。

    BM25 需要精确词项，因此显式加入：
    文件路径、符号、类型、父符号和源码。

    不直接使用 embedding_content，
    避免把为向量模型准备的中文标签重复加入。
