    metadata = chunk.metadata

    fields = [
        chunk.source,
    ]

    for key in (
        "symbol",
        "symbol_type",
        "parent_symbol",
    ):
        value = metadata.get(key)

        if isinstance(value, str) and value:
            fields.append(value)

    fields.append(chunk.content)

    return "\n".join(fields)

