def __init__(
    self,
    index: InMemoryBM25Index,
) -> None:
    self.index = index

def retrieve(
    self,
    query: str,
    top_k: int = 5,
    minimum_score: float | None = None,
) -> list[SearchResult]:
    return self.index.search(
        query=query,
        top_k=top_k,
        minimum_score=minimum_score,
    )

def __init__(
    self,
    chunk_size: int = 800,
    chunk_overlap: int = 100,
    minimum_chunk_ratio: float = 0.5,
    separators: Iterable[str] | None = None,
) -> None:
    if chunk_size <= 0:
        raise ValueError("chunk_size must be greater than 0")

    if chunk_overlap < 0:
        raise ValueError("chunk_overlap cannot be negative")

    if chunk_overlap >= chunk_size:
        raise ValueError("chunk_overlap must be smaller than chunk_size")

    if not 0 < minimum_chunk_ratio <= 1:
        raise ValueError("minimum_chunk_ratio must be within (0, 1]")

    self.chunk_size = chunk_size
    self.chunk_overlap = chunk_overlap
    self.minimum_chunk_ratio = minimum_chunk_ratio

    self.separators = tuple(
        separators if separators is not None else self.DEFAULT_SEPARATORS
    )

def split_documents(
    self,
    documents: list[Document],
) -> list[Chunk]:
    chunks: list[Chunk] = []

    for document in documents:
        chunks.extend(self.split_document(document))

    return chunks

def _find_split_end(
    self,
    text: str,
    start: int,
    hard_end: int,
) -> int:
    """
    在不超过 hard_end 的范围内寻找合适的结束位置。
    不允许为了寻找边界而让 Chunk 过短。
    """

    if hard_end >= len(text):
        return len(text)

    minimum_size = max(1, int(self.chunk_size * self.minimum_chunk_ratio))

    search_start = min(start + minimum_size, hard_end)

    for separator in self.separators:
        position = text.rfind(
            separator,
            search_start,
            hard_end,
        )

        if position == -1:
            continue

        return position + len(separator)

    return hard_end

@staticmethod
def _trim_span(
    text: str,
    start: int,
    end: int,
) -> tuple[int, int]:
    """去除Chunk两端空白"""

    while start < end and text[start].isspace():
        start += 1

    while start < end and text[end - 1].isspace():
        end -= 1

    return start, end

