def _format_item(
    self,
    item: ContextItem,
) -> str:
    chunk = item.chunk
    metadata = chunk.metadata

    header_lines = [
        f"[{item.context_id}]",
        f"来源：{chunk.source}",
    ]

    symbol = metadata.get("symbol")

    if symbol:
        header_lines.append(f"符号：{symbol}")

    symbol_type = metadata.get("symbol_type")

    if symbol_type:
        header_lines.append(f"类型：{symbol_type}")

    start_line = metadata.get("start_line")
    end_line = metadata.get("end_line")

    if isinstance(start_line, int) and isinstance(end_line, int):
        header_lines.append(f"行号：{start_line}-{end_line}")
    else:
        header_lines.append(
            "位置：字符 " f"{chunk.start_char}-" f"{chunk.end_char}"
        )

    part_index = metadata.get("part_index")
    part_count = metadata.get("part_count")

    if (
        isinstance(part_index, int)
        and isinstance(part_count, int)
        and part_count > 1
    ):
        header_lines.append("片段：" f"{part_index + 1}/" f"{part_count}")

    symbol_start = metadata.get("symbol_start_line")
    symbol_end = metadata.get("symbol_end_line")

    if isinstance(symbol_start, int) and isinstance(symbol_end, int):
        header_lines.append("完整符号范围：" f"{symbol_start}-" f"{symbol_end}")

    if self.include_scores:
        header_lines.extend(
            [
                ("检索排名：" f"{item.retrieval_rank}"),
                ("检索分数：" f"{item.score:.6f}"),
            ]
        )

    header = "\n".join(header_lines)

    return f"{header}\n\n" f"{chunk.content}"

def embed_documents(
    self,
    texts: Sequence[str],
) -> FloatMatrix:
    """
    批量生成文档向量。

    返回：
        （文档数量，向量维度）
    """

    validated_texts = self._validate_texts(
        texts=texts,
        name="documents",
    )

    if not validated_texts:
        return np.empty(
            shape=(0, self.dimension),
            dtype=np.float32,
        )

    return self._encode(validated_texts)

def _encode(
    self,
    texts: Sequence[str],
) -> FloatMatrix:
    embeddings = self.model.encode(
        list(texts),
        batch_size=self.batch_size,
        show_progress_bar=self.show_progress_bar,
        convert_to_numpy=True,
        normalize_embeddings=self.normalize_embeddings,
    )

    matrix = np.asarray(
        embeddings,
        dtype=np.float32,
    )

    if matrix.ndim == 1:
        matrix = matrix.reshape(1, -1)

    if matrix.ndim != 2:
        raise ValueError("Embedding result must be a two-dimensional matrix")

    if matrix.shape[1] != self.dimension:
        raise ValueError(
            f"Unexpected embedding dimension: expected {self.dimension}, got {matrix.shape[1]}"
        )

    return matrix

def _build_query_input(
    self,
    query: str,
) -> str:
    if not self.query_instruction:
        return query

    return f"{self.query_instruction}{query}"

@classmethod
def _validate_texts(
    cls,
    texts: Sequence[str],
    name: str,
) -> list[str]:
    validated: list[str] = []

    for index, text in enumerate(texts):
        validated.append(
            cls._validate_text(
                text=text,
                name=f"{name}[{index}]",
            )
        )

    return validated

