def __init__(
    self,
    prompt_builder: RAGPromptBuilder | None = None,
    chat_function: ChatFunction = chat,
) -> None:
    self.prompt_builder = (
        prompt_builder if prompt_builder is not None else RAGPromptBuilder()
    )

    self.chat_function = chat_function

def retrieve(
    self,
    query: str,
    top_k: int = 5,
    minimum_score: float | None = None,
) -> list[SearchResult]:
    if not isinstance(query, str):
        raise TypeError("query must be a string")

    if top_k <= 0:
        raise ValueError("top_k must be greater than 0")

    if minimum_score is not None and not math.isfinite(minimum_score):
        raise ValueError("minimum_score must be finite")

    if not query.strip():
        return []

    candidate_k = top_k * self.candidate_multiplier

    dense_results = self.dense_retriever.retrieve(
        query=query,
        top_k=candidate_k,
        minimum_score=None,
    )

    lexical_results = self.lexical_retriever.retrieve(
        query=query,
        top_k=candidate_k,
        minimum_score=None,
    )

    fused_scores: dict[str, float] = {}
    chunks_by_id: dict[str, Chunk] = {}
    best_channel_rank: dict[str, int] = {}

    self._accumulate_results(
        results=dense_results,
        weight=self.dense_weight,
        fused_scores=fused_scores,
        chunks_by_id=chunks_by_id,
        best_channel_rank=(best_channel_rank),
    )

    self._accumulate_results(
        results=lexical_results,
        weight=self.lexical_weight,
        fused_scores=fused_scores,
        chunks_by_id=chunks_by_id,
        best_channel_rank=(best_channel_rank),
    )

    ranked_chunk_ids = sorted(
        fused_scores,
        key=lambda chunk_id: (
            -fused_scores[chunk_id],
            best_channel_rank[chunk_id],
            chunks_by_id[chunk_id].source,
            chunk_id,
        ),
    )

    results: list[SearchResult] = []

    for chunk_id in ranked_chunk_ids:
        score = fused_scores[chunk_id]

        if minimum_score is not None and score < minimum_score:
            continue

        results.append(
            SearchResult(
                chunk=chunks_by_id[chunk_id],
                score=score,
                rank=len(results) + 1,
            )
        )

        if len(results) >= top_k:
            break

    return results

