@staticmethod
def _node_start_line(
    node: ast.AST,
) -> int:
    lineno = getattr(
        node,
        "lineno",
        None,
    )

    if lineno is None:
        raise ValueError("AST node has no start line")

    decorators = getattr(
        node,
        "decorator_list",
        [],
    )

    decorator_lines = [
        decorator.lineno
        for decorator in decorators
        if hasattr(
            decorator,
            "lineno",
        )
    ]

    if decorator_lines:
        return min(
            lineno,
            *decorator_lines,
        )

    return lineno

