@staticmethod
def _build_chunk_id(
    document_id: str,
    span: PythonSpan,
    part: PythonPart,
    content: str,
) -> str:
    raw_id = (
        f"{document_id}\0"
        f"{span.symbol}\0"
        f"{span.symbol_type}\0"
        f"{part.start_line}\0"
        f"{part.end_line}\0"
        f"{content}"
    )

    digest = hashlib.sha256(raw_id.encode("utf-8")).hexdigest()[:16]

    return (
        f"{document_id}:" f"{span.symbol}:" f"part_{part.part_index}:" f"{digest}"
    )

def __init__(
    self,
    ignored_directories: set[str] | None = None,
) -> None:
    self.ignored_directories = (
        set(ignored_directories)
        if ignored_directories is not None
        else set(self.DEFAULT_IGNORED_DIRECTORIES)
    )

def load_directory(
    self,
    directory: str | Path,
) -> list[Document]:
    root = self._resolve_directory(directory)

    documents: list[Document] = []

    for file_path in self.discover_files(root):
        document = self.load_file(
            file_path=file_path,
            root=root,
        )

        if document.content.strip():
            documents.append(document)

    return documents

def load_file(
    self,
    file_path: str | Path,
    root: str | Path | None = None,
) -> Document:
    path = Path(file_path).resolve()

    if not path.exists():
        raise FileNotFoundError(f"Python file does not exist: {path}")

    if not path.is_file():
        raise ValueError(f"Python path is not a file: {path}")

    if path.suffix.lower() != ".py":
        raise ValueError(f"Not a Python file: {path}")

    root_path = Path(root).resolve() if root is not None else None

    source = self._build_source(
        file_path=path,
        root=root_path,
    )

    # tokenize.open() 会遵循 Python 文件开头的 encoding 声明，比固定使用 UTF-8 更适合源码。
    with tokenize.open(path) as file:
        content = file.read()

    return Document(
        id=f"python:{source}",
        content=content,
        source=source,
        metadata={
            "file_name": path.name,
            "extension": ".py",
            "absolute_path": str(path),
            "language": "python",
            "source_type": "python_source",
        },
    )

def _should_ignore(
    self,
    file_path: Path,
    root: Path,
) -> bool:
    relative_path = file_path.relative_to(root)

    return any(
        part in self.ignored_directories for part in relative_path.parts[:-1]
    )

@staticmethod
def _resolve_directory(
    directory: str | Path,
) -> Path:
    root = Path(directory).resolve()

    if not root.exists():
        raise FileNotFoundError("Python project does not exist: " f"{root}")

    if not root.is_dir():
        raise NotADirectoryError(
            "Python project path is not " f"a directory: {root}"
        )

    return root

