@staticmethod
def _strip_code_fence(
    text: str,
) -> str:
    if not text.startswith("```"):
        return text

    lines = text.splitlines()

    if len(lines) < 3:
        return text

    if not lines[-1].strip().startswith("```"):
        return text

    return "\n".join(lines[1:-1]).strip()

