def rerank(
    self,
    query: str,
    results: list[SearchResult],
) -> list[SearchResult]:
    if not isinstance(query, str):
        raise TypeError("query must be a string")

    normalized_query = query.strip()

    if not normalized_query:
        return []

    if not results:
        return []

    pairs = [
        (
            normalized_query,
            self._build_passage(result.chunk),
        )
        for result in results
    ]

    model = self._get_model()

    raw_scores = model.predict(
        pairs,
        batch_size=self.batch_size,
        show_progress_bar=(self.show_progress_bar),
        convert_to_numpy=True,
    )

    scores = np.asarray(
        raw_scores,
        dtype=np.float32,
    ).reshape(-1)

    if len(scores) != len(results):
        raise RuntimeError("Reranker returned an " "unexpected number of scores")

    if not np.isfinite(scores).all():
        raise RuntimeError("Reranker returned " "non-finite scores")

    scored_results = [
        (
            result,
            float(score),
        )
        for result, score in zip(
            results,
            scores,
            strict=True,
        )
    ]

    scored_results.sort(
        key=lambda item: (
            -item[1],
            # 分数相同时保留原始
            # retrieval rank 作为稳定 tie-breaker。
            item[0].rank,
            item[0].chunk.id,
        )
    )

    return [
        SearchResult(
            chunk=result.chunk,
            score=score,
            rank=index + 1,
        )
        for index, (
            result,
            score,
        ) in enumerate(scored_results)
    ]

def _get_model(
    self,
) -> CrossEncoder:
    if self._model is None:
        self._model = CrossEncoder(
            model_name_or_path=(self.model_name),
            max_length=self.max_length,
            device=self.device,
        )

    return self._model

def __init__(
    self,
    max_results_per_symbol: int = 2,
) -> None:
    if max_results_per_symbol <= 0:
        raise ValueError("max_results_per_symbol " "must be greater than 0")

    self.max_results_per_symbol = max_results_per_symbol

def diversify(
    self,
    results: Sequence[SearchResult],
    top_k: int,
) -> list[SearchResult]:
    if top_k <= 0:
        raise ValueError("top_k must be greater than 0")

    selected: list[SearchResult] = []

    group_counts: dict[
        tuple[str, str],
        int,
    ] = {}

    seen_chunk_ids: set[str] = set()

    for result in results:
        chunk = result.chunk

        if chunk.id in seen_chunk_ids:
            continue

        group_key = self._build_group_key(result)

        if group_key is not None:
            current_count = group_counts.get(
                group_key,
                0,
            )

            if current_count >= self.max_results_per_symbol:
                continue

        selected.append(result)
        seen_chunk_ids.add(chunk.id)

        if group_key is not None:
            group_counts[group_key] = (
                group_counts.get(
                    group_key,
                    0,
                )
                + 1
            )

        if len(selected) >= top_k:
            break

    return [
        SearchResult(
            chunk=result.chunk,
            score=result.score,
            rank=index + 1,
        )
        for index, result in enumerate(selected)
    ]

