def __init__(
    self,
    embedding_client: EmbeddingClient,
    vector_store: VectorStore,
) -> None:
    if embedding_client.dimension != vector_store.dimension:
        raise ValueError(
            f"Embedding client and vector store dimension do not match: {embedding_client.dimension} != {vector_store.dimension}"
        )

    self.embedding_client = embedding_client
    self.vector_store = vector_store

def answer(
    self,
    question: str,
    top_k: int = 5,
    minimum_score: float | None = None,
) -> RAGAnswer:
    search_response = self.search(
        query=question,
        top_k=top_k,
        minimum_score=minimum_score,
    )

    context = search_response.context

    if context.is_empty:
        return RAGAnswer(
            question=question,
            answer=("知识库中没有检索到可用于回答" "该问题的资料。"),
            context=context,
            search_results=(search_response.search_results),
        )

    generated_answer = self.generator.generate(
        question=question,
        context=context,
    )

    return RAGAnswer(
        question=question,
        answer=generated_answer,
        context=context,
        search_results=(search_response.search_results),
    )

def __init__(
    self,
    dimension: int,
) -> None:
    if dimension <= 0:
        raise ValueError("dimension must be greater than 0")

    self.dimension = dimension

    self._chunks: list[Chunk] = []

    self._vectors = np.empty(
        shape=(0, dimension),
        dtype=np.float32,
    )

    self._id_to_position: dict[str, int] = {}

@property
def is_empty(self) -> bool:
    return not self._chunks

@property
def chunks(self) -> tuple[Chunk, ...]:
    """
    返回只读形式的 Chunk 集合。

    tuple 可以避免调用者直接对内部 list 执行append。
    """

    return tuple(self._chunks)

def delete(
    self,
    chunk_ids: Iterable[str],
) -> int:
    """
    删除指定 Chunk。

    返回实际删除数量。
    不存在的 ID 会被忽略。
    """

    ids_to_delete = set(chunk_ids)

    if not ids_to_delete:
        return 0

    keep_positions = [
        position
        for position, chunk in enumerate(self._chunks)
        if chunk.id not in ids_to_delete
    ]

    deleted_count = len(self._chunks) - len(keep_positions)

    if deleted_count == 0:
        return 0

    self._chunks = [self._chunks[position] for position in keep_positions]

    if keep_positions:
        self._vectors = self._vectors[
            np.asarray(
                keep_positions,
                dtype=np.int64,
            )
        ]

    else:
        self._vectors = np.empty(
            shape=(0, self.dimension),
            dtype=np.float32,
        )

    self._rebuild_id_positions()

    return deleted_count

def _validate_matrix(
    self,
    vectors: FloatMatrix,
    expected_rows: int,
) -> FloatMatrix:
    matrix = np.asarray(
        vectors,
        dtype=np.float32,
    )

    if matrix.ndim != 2:
        raise ValueError("vectors must be a two-dimensional matrix")

    if matrix.shape[0] != expected_rows:
        raise ValueError(
            f"Chunk and vector counts do not match: {expected_rows} chunks, {matrix.shape[0]} vectors"
        )

    if matrix.shape[1] != self.dimension:
        raise ValueError(
            f"Unexpected vector dimension: expected {self.dimension}, got {matrix.shape[1]}"
        )

    if not np.all(np.isfinite(matrix)):
        raise ValueError("vectors contain NaN or infinity")

    return matrix

