def search_code(repo_path: str, keyword: str, max_results: int = 20):
    root = Path(repo_path).resolve()

    if not root.exists():
        return {
            "success": False,
            "error": f"Path not found: {repo_path}",
        }

    if not root.is_dir():
        return {
            "success": False,
            "error": f"Path is not a directory: {repo_path}",
        }

    if not keyword.strip():
        return {
            "success": False,
            "error": "Keyword cannot be empty",
        }

    if not 1 <= max_results <= MAX_SEARCH_RESULTS:
        return {
            "success": False,
            "error": (f"max_results must be between 1 and {MAX_SEARCH_RESULTS}"),
        }

    matches = []
    normalized_keyword = keyword.lower()

    for file, relative_path in iter_repository_files(root):
        try:
            content = file.read_text(encoding="utf-8")
        except (UnicodeDecodeError, PermissionError, OSError):
            continue

        lines = content.splitlines()

        for line_number, line in enumerate(lines, start=1):
            if normalized_keyword not in line.lower():
                continue

            matches.append(
                {
                    "file_path": relative_path.as_posix(),
                    "line": line_number,
                    "content": line.strip(),
                }
            )

            if len(matches) >= max_results:
                return {
                    "success": True,
                    "repo_path": str(root),
                    "keyword": keyword,
                    "matches": matches,
                    "truncated": True,
                }

    return {
        "success": True,
        "repo_path": str(root),
        "keyword": keyword,
        "matches": matches,
        "truncated": False,
    }

